export const REGENCY_BY_GEO = Object.fromEntries(
  REGENCIES.map((r) => [r.geoKey, r]),
) as Record<string, RegencyUnit>;

export function regenciesByParent(parentProvinceKey: string): RegencyUnit[] {
  return REGENCIES.filter((r) => r.parentProvinceKey === parentProvinceKey);
}
